import pandas as pd, numpy as np, warnings
warnings.filterwarnings('ignore')
imp = pd.read_csv('data/impressions.csv')
conv = pd.read_csv('data/conversions.csv')
m = imp.merge(conv, on='impression_id', how='left')
m['y'] = m.conversion_value.notna().astype(int)

from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import cross_val_score
from sklearn.metrics import log_loss

base = pd.get_dummies(m[['arm_id','hour_of_day','day_of_week','user_segment','device_type']],
                   columns=['arm_id','hour_of_day','day_of_week','user_segment','device_type'], drop_first=True)

Xf = base.copy()
for h in range(24):
    for a in range(1,10):
        Xf[f'a{a}h{h}'] = ((m.arm_id==a)*(m.hour_of_day==h)).astype(float)
for d in range(7):
    for a in range(1,10):
        Xf[f'a{a}d{d}'] = ((m.arm_id==a)*(m.day_of_week==d)).astype(float)
for s in ['young','senior']:
    for a in range(1,10):
        Xf[f'a{a}s{s}'] = ((m.arm_id==a)*(m.user_segment==s)).astype(float)
for dv in ['mobile','tablet']:
    for a in range(1,10):
        Xf[f'a{a}v{dv}'] = ((m.arm_id==a)*(m.device_type==dv)).astype(float)

# 5-fold CV logloss for main effects vs full interactions
for name, X, C in [("main", base, 1.0), ("full int C=1", Xf, 1.0), ("full int C=0.3", Xf, 0.3), ("full int C=0.1", Xf, 0.1)]:
    lr = LogisticRegression(max_iter=5000, C=C)
    scores = cross_val_score(lr, X, m.y, cv=5, scoring='neg_log_loss')
    print(name, "CV logloss:", round(-scores.mean(),5), "±", round(scores.std(),5))
